export function shouldShowIncognitoBanner(params: {
  allowed: boolean | null;
  dismissed: boolean;
  routeModes: readonly OpenMode[];
}): boolean {
  if (params.allowed !== false || params.dismissed) return false;
  return params.routeModes.some((m) => m === "incognito" || m === "both");
}

export function planTabGroups(tabs: readonly OpenedTab[]): PlannedTabGroup[] {
  const byKey = new Map<string, PlannedTabGroup>();
  for (const tab of tabs) {
    const label = tab.label?.trim();
    if (!label) continue;
    const key = `${tab.mode}\u0000${label}`;
    let group = byKey.get(key);
    if (!group) {
      group = { title: label, color: colorForLabel(label), tabIds: [] };
      byKey.set(key, group);
    }
    group.tabIds.push(tab.tabId);
  }
  return [...byKey.values()];
}

runtime?.onMessage?.addListener((message, _sender, sendResponse) => {
  if (!isLaunchMessage(message)) return false;

  const pending = handleLaunchMessage(message);
  if (typeof sendResponse === "function") {
    const respond = sendResponse as (response: LaunchResponse) => void;
    void pending.then(respond).catch((e: unknown) => {
      respond({ ok: false, error: e instanceof Error ? e.message : String(e) });
    });
    return true;
  }

  return pending;
});

export function resolveOmniboxInput(
  routes: readonly Route[],
  text: string,
): Route | undefined {
  const trimmed = text.trim();
  if (!trimmed) return undefined;
  try {
    const canonical = canonicalizeUrl(trimmed);
    const exact = routes.find((r) => canonicalizeUrl(r.url) === canonical);
    if (exact) return exact;
  } catch {
    // not a URL: fall through to text search
  }
  return searchRoutes(routes, { text: trimmed })[0];
}

export function isReminderDue(params: {
  lastOpenedAt?: string;
  intervalHours: number;
  nowMs: number;
}): boolean {
  const intervalMs = hoursToMs(normalizeIntervalHours(params.intervalHours));
  const lastOpenedMs = parseIsoToMs(params.lastOpenedAt);
  if (lastOpenedMs === null) return true;
  return params.nowMs - lastOpenedMs >= intervalMs;
}

