it("plural blocks cover every plural category of the language", () => {
  const needed = new Intl.PluralRules(code).resolvedOptions().pluralCategories;
  const problems: string[] = [];
  for (const [k, v] of Object.entries(dict)) {
    for (const b of findPluralBlocks(v)) {
      for (const sel of b.options.keys()) {
        if (!sel.startsWith("=") && !needed.includes(sel as Intl.LDMLPluralRule)) problems.push(`${k}: unknown "${sel}"`);
      }
      for (const cat of needed) if (!b.options.has(cat)) problems.push(`${k}: missing "${cat}"`);
    }
  }
  expect(problems).toEqual([]);
});

